/**
 * overlap-detector.ts —— 重叠检测纯函数
 * 3 个维度：时间冲突、资源争抢、依赖交汇
 * 全部纯函数，可独立单测
 */
export interface TaskForOverlap {
    id: string;
    title: string;
    assigneeId: string | null;
    assigneeName?: string;
    start: string;
    end: string;
    estimatedHours: number;
    status: string;
    isOnCriticalPath?: boolean;
}
export interface DependencyForOverlap {
    id: string;
    prevTaskId: string;
    nextTaskId: string;
    isShared: boolean;
    type: string;
}
export type OverlapSeverity = 'low' | 'medium' | 'high';
export interface TimeConflict {
    assigneeId: string;
    assigneeName: string;
    taskIds: string[];
    taskTitles: string[];
    overlapStart: string;
    overlapEnd: string;
    overlapDays: number;
    severity: OverlapSeverity;
}
export interface ResourceConflict {
    assigneeId: string;
    assigneeName: string;
    date: string;
    totalHours: number;
    threshold: number;
    taskCount: number;
    taskIds: string[];
    severity: OverlapSeverity;
}
export interface DependencyHub {
    hubTaskId: string;
    hubTaskTitle: string;
    downstreamCount: number;
    downstreamTasks: {
        id: string;
        title: string;
    }[];
    isOnCriticalPath: boolean;
    benefitScore: number;
}
export interface OverlapSummary {
    timeConflicts: number;
    resourceConflicts: number;
    dependencyHubs: number;
    totalAffectedTasks: number;
    severity: OverlapSeverity;
}
export interface OverlapResult {
    projectId: string;
    generatedAt: string;
    summary: OverlapSummary;
    dimensions: {
        time: TimeConflict[];
        resource: ResourceConflict[];
        dependency: DependencyHub[];
    };
}
/**
 * 时间冲突：同一人在重叠时间段内有 2+ 个进行中/待办任务
 * 用并查集合并冲突组（A 撞 B，B 撞 C，A B C 同一组）
 */
export declare function detectTimeConflicts(tasks: TaskForOverlap[]): TimeConflict[];
/**
 * 资源争抢：同一人同一天被分配的估时 > 阈值
 * 假设：任务在 [start, end] 区间内平均分配每日工时 = estimatedHours / 总天数
 */
export declare function detectResourceConflicts(tasks: TaskForOverlap[], thresholdHoursPerDay?: number): ResourceConflict[];
/**
 * 依赖交汇：is_shared=true 的前置任务有 2+ 个下游
 * benefitScore = 下游数 × 下游任务平均估时
 */
export declare function detectDependencyHubs(tasks: TaskForOverlap[], deps: DependencyForOverlap[]): DependencyHub[];
/**
 * 综合重叠检测结果
 */
export declare function detectOverlaps(projectId: string, tasks: TaskForOverlap[], deps: DependencyForOverlap[], options?: {
    resourceThreshold?: number;
    dimensions?: ('time' | 'resource' | 'dependency')[];
}): OverlapResult;
